// 清算明细显示原移交数量/货权和当时遗留，不用今天库存反推旧责任。
#include "task_static_asset_view.hpp"
namespace hanmo::resident {namespace {
using V=BoundaryValue;
// 本人只读源带完整World身份；恢复或推进后旧翻页回调不得取代新来源。
V identity(const WorldIdentity& source){StableId id;constexpr char hex[]="0123456789abcdef";for(const auto byte:source.world_id){id+=hex[byte>>4];id+=hex[byte&15];}return boundary::obj({{"world_id",V{id}},{"execution_epoch",V{source.execution_epoch}},{"revision",V{source.revision}},{"tick",V{source.tick}}});}
// 来源权限每次独立核原人物角色；单改派生索引不能曝光另一人的实物流水。
bool known(const TaskStaticAssetReceipt& row,const StableId& actor){return row.assignee_actor_id==actor;}
// 原清算完整余货用于规则核验；本人只看到原办理行囊内的历史批次，不泄露远方位置。
std::vector<const TaskStaticAssetRemainder*> visible_remainders(const TaskStaticAssetReceipt& row){std::vector<const TaskStaticAssetRemainder*> out;for(const auto& lot:row.retained_task_goods)if(lot.inventory_id==row.from_inventory_id)out.push_back(&lot);return out;}
}
Outcome<BoundaryValue> query_task_static_assets(const CommonStore& common,const TaskState& tasks,const TaskCatalog& catalog,const TaskStaticAssetState& state,Integer cursor,const StableId& receipt_id,Integer lot_cursor){
    const auto fail=[](const StableId& code)->Outcome<V>{return {false,{},common_failure(code,"task_static_assets").error};};const auto& observer=common.state().metadata.player_actor_id;if(!common.actor(observer))return fail("UnknownPlayer");if(state.version!=1)return fail("UnsupportedTaskStaticAssetVersion");if(cursor<0||lot_cursor<0)return fail("InvalidTaskStaticAssetCursor");
    const auto found=state.observed_by.find(observer);const auto size=found==state.observed_by.end()?0:found->second.size();if(static_cast<std::size_t>(cursor)>size)return fail("InvalidTaskStaticAssetCursor");
    V::Array rows,lots;Integer next=cursor;
    const auto checked=[&](const StableId& id)->const TaskStaticAssetReceipt*{const auto* row=state.receipts.find(id);const auto* task=row?tasks.tasks.find(row->task_id):nullptr;const auto* definition=task?catalog.offers.find(task->offer_id):nullptr;const auto* head=common.state().facts.find(id);if(!row||!known(*row,observer)||!head||head->id!=id||head->kind!=task_static_asset_fact_kind||head->domain!="tasks"||!task||!definition||task->contract_id||row->assignee_actor_id!=task->assignee||row->offer_id!=task->offer_id||!owner_equal(row->original_issuer,definition->issuer)||row->tick<task->accepted_tick||row->tick>common.tick())return nullptr;return row;};
    for(;static_cast<std::size_t>(next)<size&&rows.size()<16;++next){const auto& id=found->second[static_cast<std::size_t>(next)];const auto* row=checked(id);if(!row)return fail("TaskStaticAssetObserverIndexMismatch");const auto* task=tasks.tasks.find(row->task_id);const auto* definition=catalog.offers.find(row->offer_id);rows.push_back(boundary::obj({{"receipt_id",V{id}},{"task_id",V{row->task_id}},{"display_name",V{definition->display_name}},{"stage",V{row->stage}},{"stage_text",V{StableId{row->stage=="procurement_delivery"?"原物交货":"原物返还"}}},{"observed_tick",V{row->tick}},{"settlement_id",V{task->settlement_id}},{"transferred_batches",V{static_cast<Integer>(row->legs.size())}},{"retained_batches",V{static_cast<Integer>(visible_remainders(*row).size())}},{"explanation",V{StableId{row->retained_task_goods.empty()?"当次办理后没有遗留任务货物；钱款、其他责任和继产资格仍由原账分别核验。":"当次办理后仍有原任务责任；这里只列本人原办理行囊所留批次，其他原件仅供规则核验。"}}}}));}
    V::Dict page{{"ok",V{true}},{"observer_actor_id",V{observer}},{"source_identity",identity(common.state().identity)},{"cursor",V{cursor}},{"rows",V{std::move(rows)}},{"receipt_id",V{receipt_id}},{"lot_cursor",V{lot_cursor}}};if(static_cast<std::size_t>(next)<size)page.emplace_back("next_cursor",V{next});
    if(!receipt_id.empty()){
        if(found==state.observed_by.end()||std::count(found->second.begin(),found->second.end(),receipt_id)!=1)return fail("TaskStaticAssetNotKnown");const auto* row=checked(receipt_id);if(!row)return fail("TaskStaticAssetObserverIndexMismatch");const auto visible=visible_remainders(*row);const auto total=row->legs.size()+visible.size();if(static_cast<std::size_t>(lot_cursor)>total)return fail("InvalidTaskStaticAssetCursor");Integer end=lot_cursor;
        for(;static_cast<std::size_t>(end)<total&&lots.size()<16;++end){if(static_cast<std::size_t>(end)<row->legs.size()){const auto& leg=row->legs[static_cast<std::size_t>(end)];lots.push_back(boundary::obj({{"kind",V{StableId{"transferred"}}},{"item_id",V{leg.item_id}},{"quantity",V{leg.quantity}},{"source_lot_id",V{leg.source_lot_id}},{"destination_lot_id",V{leg.destination_lot_id}},{"from_inventory_id",V{row->from_inventory_id}},{"to_inventory_id",V{row->to_inventory_id}},{"source_owner",boundary::encode_owner(leg.source_owner)},{"destination_owner",boundary::encode_owner(leg.destination_owner)},{"reservation",boundary::encode_reservation_ref(leg.reservation,true)}}));}else{const auto& lot=*visible[static_cast<std::size_t>(end)-row->legs.size()];lots.push_back(boundary::obj({{"kind",V{StableId{"retained_at_settlement"}}},{"item_id",V{lot.item_id}},{"quantity",V{lot.quantity}},{"source_lot_id",V{lot.lot_id}},{"from_inventory_id",V{lot.inventory_id}},{"reservation",boundary::encode_reservation_ref(lot.reservation,true)}}));}}
        if(static_cast<std::size_t>(end)<total)page.emplace_back("next_lot_cursor",V{end});
    }else if(lot_cursor!=0)return fail("InvalidTaskStaticAssetCursor");page.emplace_back("lots",V{std::move(lots)});return {true,V{std::move(page)},{}};
}
}
